#pragma once
// Compile-time configuration.
// DO NOT edit this file by hand! The values come from the -D macros passed in by the
// Makefile (OPERAND_WIDTH / TEST_SIGNED / TEST_EXHAUSTIVE), which follow the `make menuconfig`
// settings.
#include <cstdint>
#include <limits>

namespace sim {
using U128 = unsigned __int128;

/// Operand width in bits (1-64); "Operand width" in menuconfig.
constexpr unsigned width = OPERAND_WIDTH;
/// Whether signed and mixed-sign multiplication is tested (stage 5 only).
constexpr bool testSigned = TEST_SIGNED;
/// Whether the test is exhaustive.
constexpr bool testExhaustive = TEST_EXHAUSTIVE;
static_assert(width >= 1 && width <= 64);
/// Operand mask: the low `width` bits are 1.
constexpr uint64_t operandMask = std::numeric_limits<uint64_t>::max() >> (64 - width);
/// Product mask: the low 2*width bits are 1.
constexpr U128 resultMask = ~U128{0} >> (128 - 2 * width);
} // namespace sim
